python3 -c 'import json,pathlib,zlib,difflib; p=pathlib.Path("docs/research/poc/pair"); s=json.loads((p/"replay-0105-status.json").read_text()); rows=[]; versions={}; summary=[]
for q in s["runs"]:
 d=json.loads(pathlib.Path(q["output"]).read_text()); row=next(r for r in d["resources"] if r["type"]=="BDHb"); heaps=[]
 for side in ("left","right"):
  raw=pathlib.Path(d["inputs"][side]["path"]).read_bytes(); off=row[side]["file_payload_offset"]; size=row[side]["length"]; heaps.append(zlib.decompress(raw[off+4:off+size]))
 edits=[{"tag":tag,"left_offset":a,"right_offset":b,"left_hex":heaps[0][a:ae].hex(),"right_hex":heaps[1][b:be].hex()} for tag,a,ae,b,be in difflib.SequenceMatcher(None,*heaps,autojunk=False).get_opcodes() if tag!="equal"]; rows.append({"source":q["output"],"resource":{"type":"BDHb","id":0,"occurrence":0},"method":"difflib.SequenceMatcher(autojunk=False); byte alignment hypothesis, not a semantic parse","edits":edits}); summary.append({"file":pathlib.Path(q["output"]).name,"differing_resources":d["differing_resources"],"resource_counts":[sum(r[x] is not None for r in d["resources"]) for x in ("left","right")],"name_changes":[r["type"] for r in d["resources"] if r["name_changed"]]})
 for side in ("left","right"):
  versions[d["inputs"][side]["path"]]=[{"type":r["type"],"id":r["id"],"raw_hex":r["version_fields"][side]["raw_hex"],"tuple":r["version_fields"][side]["tuple_major_minor_patch_phase_build"],"parser_value":r["version_fields"][side]["parser_value"]} for r in d["resources"] if "version_fields" in r and r[side] is not None]
result={"schema_version":1,"limitations":["Sequence alignment is ambiguous; edits are candidate byte correspondences only, not type/value encoding rules."],"bdhb_alignments":rows,"version_declarations":versions,"comparison_summary":summary}; (p/"candidates-0105.json").write_text(json.dumps(result,indent=2)+"\n"); print(json.dumps({"summary":summary,"logic_alignments":rows[:4],"unique_version_sets":{pathlib.Path(k).name:v for k,v in list(versions.items())[:4]}},separators=(",",":")))'
